oxy_webhelp_navlinks = {"gcp_workload_recovery-d39307e21255":{"topics":[{"title":"Evaluation of options for GCP recovery","shortdesc":"<p class=\"shortdesc\">Understanding the recovery options for GCP is essential to ensure alignment with         business needs for data consistency and availability. Thorough evaluation of these options,         including disk encryption strategies, enables informed decision-making and effective data         protection during recovery.<\/p>","href":"gcp\/evaluation_options_gcp_recovery.html","attributes":{"data-id":"evaluation_options_gcp_recovery"},"menu":{"hasChildren":false},"tocID":"evaluation_options_gcp_recovery-d39307e21269","next":"evaluation_options_gcp_recovery-d39307e21269"},{"title":"Privilege elevation for GCP recovery","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> provides you an option to secure GCP projects by using a least         permission model, granting only necessary read permissions. For recovery operations, you can         temporarily elevate permissions by authorizing a service account role.<\/p>","href":"gcp\/privilege_elevation_gcp_recovery.html","attributes":{"data-id":"privilege_elevation_gcp_recovery"},"menu":{"hasChildren":false},"tocID":"privilege_elevation_gcp_recovery-d39307e21302","next":"privilege_elevation_gcp_recovery-d39307e21302"},{"title":"File Indexing for GCE instances and disks","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> uses Exocompute on GCP to extract file system index metadata from         the persistent disk snapshots created when protecting GCE instances and persistent         disks.<\/p>","href":"gcp\/file_indexing_gce_pd.html","attributes":{"data-id":"file_indexing_gce_pd"},"menu":{"hasChildren":false},"tocID":"file_indexing_gce_pd-d39307e21326","next":"file_indexing_gce_pd-d39307e21326"},{"title":"Recovery of GCE instances and persistent disks","shortdesc":"<p class=\"shortdesc\">You can recover your GCE instances and persistent disks using options such as         recovering files or folders, exporting, and restoring.<\/p>","href":"gcp\/recover_gce_pd.html","attributes":{"data-id":"recover_gce_pd"},"menu":{"hasChildren":false},"tocID":"recover_gce_pd-d39307e21375","next":"recover_gce_pd-d39307e21375"},{"title":"Recovery of Cloud SQL instances","shortdesc":"<p class=\"shortdesc\">You can recover your Cloud SQL instances using options, such as exporting and         restoring the instances.<\/p>","href":"gcp\/gcp_recovery_cloud_sql_instances.html","attributes":{"data-id":"gcp_recovery_cloud_sql_instances"},"menu":{"hasChildren":false},"tocID":"gcp_recovery_cloud_sql_instances-d39307e21441","next":"gcp_recovery_cloud_sql_instances-d39307e21441"},{"title":"Recovery of BigQuery datasets","shortdesc":"<p class=\"shortdesc\">You can recover protected Google BigQuery datasets from the backups that <span class=\"ph\">RSC<\/span> stores in your         backup         locations.<\/p>","href":"gcp\/gcp_recovery_bigquery_datasets.html","attributes":{"data-id":"gcp_recovery_bigquery_datasets"},"menu":{"hasChildren":false},"tocID":"gcp_recovery_bigquery_datasets-d39307e21485","next":"gcp_recovery_bigquery_datasets-d39307e21485"}]}};